import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    # Ignore blank lines before the header, but keep them in the data.
    for columns in reader:
        if columns and (len(columns) > 1 or columns[0].strip()):
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(len(columns), max((len(row) for row in rows), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"extra_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
